/// Editor commands: `try await client.editor(.notePrepare(id: id))`.
public enum EditorCommands {
    public struct NotePrepare: EngineEditorSpec {
        public static let name = "note.prepare"
        public typealias Args = FoleviEngine.NotePrepareArgs
        public typealias Result = FoleviEngine.NoteShownResult
        public var args: Args
        public init(_ args: Args) { self.args = args }
    }
    public struct NoteShow: EngineEditorSpec {
        public static let name = "note.show"
        public typealias Args = FoleviEngine.NoteShowArgs
        public typealias Result = FoleviEngine.NoteShownResult
        public var args: Args
        public init(_ args: Args) { self.args = args }
    }
    public struct NoteClose: EngineEditorSpec {
        public static let name = "note.close"
